"""看板页面（由 dashboard.html 生成，编译进 exe，避免 _MEI 数据文件读取问题）。"""

PAGE = '<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>任务编排中心</title>\n<script>\n(function(){try{var t=localStorage.getItem(\'ta-theme\');\nif(!t)t=matchMedia(\'(prefers-color-scheme: light)\').matches?\'light\':\'dark\';\ndocument.documentElement.dataset.theme=t;}catch(e){document.documentElement.dataset.theme=\'dark\';}})();\n</script>\n<style>\n:root[data-theme="dark"]{\n  color-scheme:dark;\n  --bg:#0b0f17;--panel:#131a2a;--card:#1a2235;--line:#253048;--line2:#31405f;\n  --text:#e5eaf6;--dim:#94a2be;--faint:#64748f;\n  --acc:#5b8cff;--acc-strong:#3f6ef0;--acc-soft:rgba(91,140,255,.14);\n  --ok:#3ecf8e;--ok-soft:rgba(62,207,142,.13);\n  --warn:#e8a13c;--warn-soft:rgba(232,161,60,.15);\n  --bad:#e05c5c;--bad-soft:rgba(224,92,92,.14);\n  --orange:#ef7d45;--orange-soft:rgba(239,125,69,.15);\n  --shadow:0 10px 30px rgba(0,0,0,.35);\n  --tint:rgba(15,21,34,.86);\n}\n:root[data-theme="light"]{\n  color-scheme:light;\n  --bg:#f2f4f9;--panel:#ffffff;--card:#f7f8fc;--line:#e4e9f3;--line2:#cbd5ea;\n  --text:#1d2637;--dim:#5c6b85;--faint:#8e9bb3;\n  --acc:#3b6ef5;--acc-strong:#2f5ce0;--acc-soft:rgba(59,110,245,.10);\n  --ok:#0e9f6e;--ok-soft:rgba(14,159,110,.11);\n  --warn:#a8690e;--warn-soft:rgba(178,111,18,.11);\n  --bad:#d23f3f;--bad-soft:rgba(210,63,63,.10);\n  --orange:#cf5f22;--orange-soft:rgba(207,95,34,.11);\n  --shadow:0 8px 24px rgba(24,43,99,.07);\n  --tint:rgba(255,255,255,.88);\n}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml{scrollbar-color:var(--line2) transparent}\nbody{background:var(--bg);color:var(--text);\n font:14px/1.65 "Segoe UI Variable Text","Segoe UI",system-ui,-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;\n -webkit-font-smoothing:antialiased;padding-bottom:48px}\n.theming,.theming *{transition:background-color .25s ease,color .25s ease,border-color .25s ease,box-shadow .25s ease!important}\n::selection{background:var(--acc-soft)}\n::-webkit-scrollbar{width:9px;height:9px}\n::-webkit-scrollbar-thumb{background:var(--line2);border-radius:8px;border:2px solid transparent;background-clip:content-box}\n::-webkit-scrollbar-track{background:transparent}\n\n.top{position:sticky;top:0;z-index:20;background:var(--tint);backdrop-filter:blur(10px);\n border-bottom:1px solid var(--line);padding:13px 26px;display:flex;gap:14px;align-items:center;\n justify-content:space-between;flex-wrap:wrap}\n.brand{display:flex;gap:12px;align-items:center;min-width:0}\n.logo{width:38px;height:38px;border-radius:10px;flex:none;\n background:linear-gradient(135deg,var(--acc),#7a5cff);display:grid;place-items:center;\n box-shadow:0 4px 14px var(--acc-soft)}\n.logo svg{width:20px;height:20px}\nh1{font-size:17px;font-weight:650;letter-spacing:.2px}\n.sub{color:var(--dim);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:46vw}\n.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.btn{display:inline-flex;gap:6px;align-items:center;background:var(--panel);border:1px solid var(--line);\n color:var(--text);padding:7px 14px;border-radius:8px;cursor:pointer;font-size:13px;font-weight:500;\n transition:border-color .15s,background .15s,transform .05s}\n.btn:hover{border-color:var(--line2);background:var(--card)}\n.btn:active{transform:translateY(1px)}\n.btn.primary{background:var(--acc);border-color:var(--acc);color:#fff;box-shadow:0 4px 14px var(--acc-soft)}\n.btn.primary:hover{background:var(--acc-strong)}\n.btn.icon{padding:7px 9px}\n.btn svg{width:15px;height:15px;flex:none}\n.btn:disabled{opacity:.55;cursor:not-allowed}\n.navseg{display:flex;background:var(--card);border:1px solid var(--line);border-radius:9px;padding:3px;gap:2px}\n.navseg button{border:0;background:transparent;color:var(--dim);padding:5px 16px;border-radius:7px;\n cursor:pointer;font-size:13px;font-weight:600;font-family:inherit}\n.navseg button.on{background:var(--acc);color:#fff;box-shadow:0 2px 8px var(--acc-soft)}\n.navseg button:not(.on):hover{color:var(--text)}\n\n.wrap{max-width:1200px;margin:0 auto;padding:18px 26px}\n.stats{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}\n.chip{display:flex;gap:8px;align-items:baseline;background:var(--panel);border:1px solid var(--line);\n border-radius:9px;padding:7px 13px;font-size:12.5px}\n.chip .cl{color:var(--faint)}\n.chip .cv{font-weight:600;font-variant-numeric:tabular-nums}\n.chip.ok .cv{color:var(--ok)}\n.chip.warn .cv{color:var(--warn)}\n.pulse{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--warn);\n margin-right:6px;animation:pulse 1.1s ease-in-out infinite}\n@keyframes pulse{50%{opacity:.25}}\n\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:16px}\n.proj{background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:hidden;\n box-shadow:var(--shadow);display:flex;flex-direction:column}\n.proj-head{display:flex;gap:8px;align-items:center;padding:13px 16px 0;flex-wrap:wrap}\n.proj-head h2{font-size:15px;font-weight:650}\n.dot{width:9px;height:9px;border-radius:3px;background:linear-gradient(135deg,var(--acc),#7a5cff);flex:none}\n.tag{font-size:11px;padding:1.5px 8px;border-radius:6px;background:var(--card);border:1px solid var(--line);color:var(--dim)}\n.tag.ok{color:var(--ok);background:var(--ok-soft);border-color:transparent}\n.tag.warn{color:var(--warn);background:var(--warn-soft);border-color:transparent}\n.tag.bad{color:var(--bad);background:var(--bad-soft);border-color:transparent}\n.counts{margin-left:auto;color:var(--faint);font-size:12px;font-variant-numeric:tabular-nums}\n.pbtns{display:flex;gap:6px;margin-left:auto}\n.pbtns button{background:transparent;border:1px solid var(--line);color:var(--dim);padding:2px 9px;\n border-radius:6px;font-size:11.5px;cursor:pointer;font-family:inherit;transition:.15s}\n.pbtns button:hover{color:var(--text);border-color:var(--line2);background:var(--card)}\n.pbtns button.danger:hover{color:var(--bad);border-color:var(--bad);background:var(--bad-soft)}\n.path{display:flex;gap:6px;align-items:center;color:var(--faint);font-size:12px;padding:4px 16px 12px;word-break:break-all}\n.path svg{width:13px;height:13px;flex:none}\n.tasks{padding:0 12px 12px;display:flex;flex-direction:column;gap:8px}\n\n.task{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 12px;\n transition:border-color .15s}\n.task:hover{border-color:var(--line2)}\n.task.err{border-color:var(--bad)}\n.t-main{display:flex;gap:8px;align-items:center}\n.pri{font-size:11px;font-weight:700;padding:1.5px 8px;border-radius:6px;flex:none;font-variant-numeric:tabular-nums}\n.pri.P0{background:var(--bad-soft);color:var(--bad)}\n.pri.P1{background:var(--orange-soft);color:var(--orange)}\n.pri.P2{background:var(--warn-soft);color:var(--warn)}\n.pri.P3{background:var(--acc-soft);color:var(--acc)}\n.pri.P4{background:var(--card);color:var(--faint);border:1px solid var(--line)}\n.title{font-weight:600;font-size:13.5px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.st{margin-left:auto;flex:none;font-size:11.5px;font-weight:600;padding:1.5px 9px;border-radius:6px}\n.st-open{color:var(--acc);background:var(--acc-soft)}\n.st-in_progress{color:var(--warn);background:var(--warn-soft)}\n.st-done{color:var(--ok);background:var(--ok-soft)}\n.st-blocked{color:var(--bad);background:var(--bad-soft)}\n.st-cancelled{color:var(--faint);background:var(--card);border:1px solid var(--line)}\n.t-meta{color:var(--faint);font-size:11.5px;margin-top:3px}\n.t-desc{color:var(--dim);font-size:12.5px;margin-top:5px;white-space:pre-wrap;cursor:pointer;\n display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}\n.t-desc.open{display:block;-webkit-line-clamp:unset}\n.ops{margin-top:8px;display:flex;gap:6px;flex-wrap:wrap}\n.ops button{background:transparent;border:1px solid var(--line);color:var(--dim);padding:2.5px 10px;\n border-radius:6px;font-size:11.5px;cursor:pointer;transition:.15s;font-family:inherit}\n.ops button:hover{color:var(--text);border-color:var(--line2);background:var(--panel)}\n.ops button.danger:hover{color:var(--bad);border-color:var(--bad);background:var(--bad-soft)}\n.empty{color:var(--faint);font-size:13px;text-align:center;padding:22px 0}\n.empty svg{width:26px;height:26px;opacity:.5;display:block;margin:0 auto 6px}\n\ndetails{margin:0 4px}\nsummary{cursor:pointer;color:var(--faint);font-size:12px;user-select:none;padding:4px 2px;list-style:none}\nsummary:hover{color:var(--dim)}\nsummary::-webkit-details-marker{display:none}\n\n.logsec{max-width:1200px;margin:20px auto 0;padding:0 26px}\n.logsec pre{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:12px 14px;\n font:11.5px/1.6 Consolas,"Cascadia Mono",monospace;max-height:380px;overflow:auto;\n white-space:pre-wrap;color:var(--dim)}\n\n/* 设置页 */\n.settings{max-width:860px;margin:0 auto;display:flex;flex-direction:column;gap:16px}\n.scard{background:var(--panel);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);padding:18px 20px}\n.scard h3{font-size:15px;margin-bottom:4px;display:flex;align-items:center;gap:8px}\n.scard .hint{color:var(--faint);font-size:12px;margin-bottom:14px}\n.frow{display:flex;gap:12px;flex-wrap:wrap}\n.frow>div{flex:1;min-width:180px}\nlabel{display:block;font-size:12px;color:var(--dim);margin:2px 0 3px}\ninput[type=text],input[type=number],input[type=password],select,textarea{\n width:100%;background:var(--card);color:var(--text);border:1px solid var(--line);border-radius:8px;\n padding:8px 10px;font:inherit;outline:none;transition:border-color .15s}\ninput:focus,select:focus,textarea:focus{border-color:var(--acc)}\ntextarea{min-height:56px;resize:vertical;line-height:1.55}\n.sfoot{display:flex;gap:8px;justify-content:flex-end;margin-top:14px;align-items:center}\n.sfoot .msg{margin-right:auto;font-size:12.5px;color:var(--ok)}\n.sfoot .msg.err{color:var(--bad)}\n.switch{position:relative;width:38px;height:21px;flex:none;display:inline-block}\n.switch input{opacity:0;width:0;height:0}\n.slider{position:absolute;inset:0;background:var(--line2);border-radius:20px;cursor:pointer;transition:.2s}\n.slider:before{content:"";position:absolute;width:15px;height:15px;left:3px;top:3px;border-radius:50%;\n background:#fff;transition:.2s}\n.switch input:checked+.slider{background:var(--acc)}\n.switch input:checked+.slider:before{transform:translateX(17px)}\n.checkline{display:flex;gap:8px;align-items:center;font-size:13px;color:var(--text);cursor:pointer;user-select:none}\n\ndialog{background:var(--panel);color:var(--text);border:1px solid var(--line2);border-radius:14px;\n padding:20px 22px;width:520px;max-width:94vw;box-shadow:var(--shadow);\n margin:auto;margin-top:max(auto,8vh);max-height:86vh;overflow:auto}\ndialog.big{width:760px}\ndialog::backdrop{background:rgba(8,12,20,.5);backdrop-filter:blur(2px)}\ndialog h3{font-size:16px;margin-bottom:10px}\ndialog .hint{color:var(--faint);font-size:12px;margin-bottom:12px}\ndialog input,dialog select,dialog textarea{margin:0 0 10px}\ndialog textarea{min-height:110px}\n.duo{display:flex;gap:10px}\n.duo>div{flex:1}\n.dlg-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:4px}\n.err{color:var(--bad);font-size:12px;min-height:17px;margin-bottom:6px}\n\n/* 目录选择器 */\n.browser{background:var(--card);border:1px solid var(--line);border-radius:9px;min-height:250px;max-height:330px;\n overflow:auto;margin-bottom:10px}\n.brow-crumb{position:sticky;top:0;background:var(--panel);padding:8px 10px;font-size:12px;color:var(--dim);\n border-bottom:1px solid var(--line);display:flex;gap:6px;align-items:center;word-break:break-all}\n.brow-crumb button{background:transparent;border:1px solid var(--line);color:var(--dim);border-radius:6px;\n padding:1px 9px;cursor:pointer;font-size:11.5px;font-family:inherit}\n.brow-crumb button:hover{color:var(--text)}\n.blist{padding:6px}\n.bitem{display:flex;gap:8px;align-items:center;padding:6px 9px;border-radius:7px;cursor:pointer;font-size:13px}\n.bitem:hover{background:var(--panel)}\n.bitem svg{width:15px;height:15px;flex:none;color:var(--warn)}\n.bitem .bpath{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--dim)}\n.bempty{color:var(--faint);text-align:center;padding:30px 0;font-size:13px}\n.pathline{display:flex;gap:8px}\n.pathline input{flex:1;margin:0}\n\n/* 指引编辑器 */\n.geditor{width:100%;min-height:380px;font:12.5px/1.7 Consolas,"Cascadia Mono",monospace;\n background:var(--card);color:var(--text);border:1px solid var(--line);border-radius:9px;\n padding:12px;outline:none;resize:vertical}\n.geditor:focus{border-color:var(--acc)}\n\n#toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%) translateY(8px);z-index:50;\n background:var(--panel);border:1px solid var(--line2);color:var(--text);padding:9px 18px;border-radius:9px;\n box-shadow:var(--shadow);font-size:13px;opacity:0;pointer-events:none;transition:.22s;max-width:80vw}\n#toast.show{opacity:1;transform:translateX(-50%) translateY(0)}\n#toast.err{border-color:var(--bad);color:var(--bad)}\n@media (max-width:640px){.sub{display:none}.wrap,.logsec{padding:14px}}\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n</style>\n</head>\n<body>\n<header class="top">\n  <div class="brand">\n    <div class="logo"><svg viewBox="0 0 24 24" fill="#fff"><rect x="3" y="4" width="5" height="16" rx="1.5" opacity=".95"/><rect x="10" y="4" width="5" height="10" rx="1.5" opacity=".7"/><rect x="17" y="4" width="4" height="13" rx="1.5" opacity=".5"/></svg></div>\n    <div><h1>任务编排中心</h1><div class="sub" id="meta"></div></div>\n  </div>\n  <div class="actions">\n    <div class="navseg">\n      <button id="tabDash" class="on" onclick="switchTab(\'dash\')">看板</button>\n      <button id="tabSet" onclick="switchTab(\'settings\')">项目与设置</button>\n    </div>\n    <button class="btn primary" id="scanBtn" onclick="doScan()"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5.5v13l11-6.5z"/></svg>立即扫描</button>\n    <button class="btn icon" onclick="refresh()" title="刷新"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M21 12a9 9 0 1 1-2.6-6.3M21 4v5h-5"/></svg></button>\n    <button class="btn icon" id="themeBtn" onclick="toggleTheme()" title="切换浅色/深色主题"></button>\n  </div>\n</header>\n\n<!-- ============ 看板视图 ============ -->\n<div id="viewDash">\n  <div class="wrap">\n    <div class="stats" id="sched"></div>\n    <div class="grid" id="projects"></div>\n  </div>\n  <div class="logsec">\n    <details open><summary>运行日志（尾部，点击收起）</summary><pre id="logs"></pre></details>\n  </div>\n</div>\n\n<!-- ============ 设置视图 ============ -->\n<div id="viewSet" style="display:none">\n  <div class="wrap settings">\n    <div class="scard">\n      <h3>🤖 大模型接入</h3>\n      <div class="hint">OpenAI 兼容协议覆盖 DeepSeek / GLM / Kimi / 通义 / Ollama 等；保存后立即生效。</div>\n      <div class="frow">\n        <div><label>协议 provider</label>\n          <select id="sProvider"><option value="openai">openai（兼容协议）</option><option value="anthropic">anthropic</option></select></div>\n        <div><label>模型 model</label><input type="text" id="sModel" placeholder="deepseek-chat"></div>\n      </div>\n      <div class="frow">\n        <div style="flex:2"><label>API 地址 base_url</label><input type="text" id="sBase" placeholder="https://api.deepseek.com/v1"></div>\n        <div style="flex:1.4"><label>API Key</label><input type="password" id="sKey" placeholder="sk-..."></div>\n      </div>\n      <div class="frow">\n        <div><label>temperature</label><input type="number" id="sTemp" step="0.1" min="0" max="2"></div>\n        <div><label>max_tokens</label><input type="number" id="sTokens" step="256" min="256"></div>\n        <div><label>请求超时（秒）</label><input type="number" id="sTimeout" min="30" max="1800"></div>\n      </div>\n      <div class="sfoot"><span class="msg" id="msgLlm"></span>\n        <button class="btn primary" onclick="saveLlm()">保存模型配置</button></div>\n    </div>\n\n    <div class="scard">\n      <h3>⏱ 调度与看板</h3>\n      <div class="hint">扫描间隔、并行数保存后立即生效；看板 host/port 变更下次启动生效。</div>\n      <div class="frow">\n        <div><label>扫描间隔（秒，30~86400）</label><input type="number" id="sInterval" min="30" max="86400"></div>\n        <div><label>并行 Agent 数</label><input type="number" id="sParallel" min="1" max="16"></div>\n        <div><label>看板端口（下次启动生效）</label><input type="number" id="sPort" min="1" max="65535"></div>\n      </div>\n      <div class="sfoot"><span class="msg" id="msgSched"></span>\n        <button class="btn primary" onclick="saveSched()">保存调度配置</button></div>\n    </div>\n\n    <div class="scard">\n      <h3>📁 受管项目</h3>\n      <div class="hint">每个项目由一个独立 Agent 负责。新建项目会自动创建任务目录与 AGENT.md。</div>\n      <div class="sfoot" style="margin:0 0 12px;justify-content:flex-start">\n        <button class="btn primary" onclick="openProjectNew()">＋ 新建项目</button>\n        <span class="msg" id="msgProj"></span>\n      </div>\n      <div id="projTable"></div>\n    </div>\n  </div>\n</div>\n\n<!-- ============ 对话框：项目 ============ -->\n<dialog id="pdlg">\n  <h3 id="pdlgTitle">新建项目</h3>\n  <div class="err" id="pdlgErr"></div>\n  <div class="duo">\n    <div><label>项目名（字母/数字/连字符）</label><input type="text" id="pName" placeholder="my-app"></div>\n    <div><label>每轮最多任务数</label><input type="number" id="pMaxTasks" value="1" min="1" max="50"></div>\n  </div>\n  <label>项目路径（本地目录）</label>\n  <div class="pathline">\n    <input type="text" id="pPath" placeholder="D:\\Repos\\my-app">\n    <button class="btn" onclick="openBrowser()">选择…</button>\n  </div>\n  <div class="duo">\n    <div><label>任务目录（相对项目根）</label><input type="text" id="pTasksDir" value="tasks"></div>\n    <div><label>指引文件</label><input type="text" id="pGuide" value="AGENT.md"></div>\n  </div>\n  <div class="duo">\n    <div><label>工具循环轮数上限</label><input type="number" id="pMaxTurns" value="40" min="5" max="200"></div>\n    <div><label>工作分支（可选，默认当前分支）</label><input type="text" id="pBranch" placeholder="main"></div>\n  </div>\n  <label>命令白名单（逗号分隔，留空用默认：python/pytest/node/npm/git…）</label>\n  <input type="text" id="pCmds" placeholder="python, pytest, npm, dotnet">\n  <label class="checkline" style="margin-top:4px">\n    <span class="switch"><input type="checkbox" id="pEnabled" checked><span class="slider"></span></span>\n    启用该项目（停用后调度器跳过，配置保留）\n  </label>\n  <div class="dlg-actions">\n    <button class="btn" onclick="pdlg.close()">取消</button>\n    <button class="btn primary" onclick="saveProject()">保存</button>\n  </div>\n</dialog>\n\n<!-- ============ 对话框：目录选择器 ============ -->\n<dialog id="bdlg">\n  <h3>选择本地目录</h3>\n  <div class="browser">\n    <div class="brow-crumb"><button onclick="browseUp()">⬆ 上一级</button><span id="bCur">（请选择盘符）</span></div>\n    <div class="blist" id="bList"></div>\n  </div>\n  <div class="pathline">\n    <input type="text" id="bManual" placeholder="或直接粘贴完整路径">\n    <button class="btn primary" onclick="pickPath()">使用此目录</button>\n  </div>\n  <div class="dlg-actions"><button class="btn" onclick="bdlg.close()">取消</button></div>\n</dialog>\n\n<!-- ============ 对话框：AGENT.md 编辑 ============ -->\n<dialog id="gdlg" class="big">\n  <h3 id="gdlgTitle">编辑 AGENT.md</h3>\n  <div class="hint" id="gdlgFile"></div>\n  <div class="err" id="gdlgErr"></div>\n  <textarea class="geditor" id="gContent" spellcheck="false"></textarea>\n  <div class="dlg-actions">\n    <button class="btn" onclick="gdlg.close()">取消</button>\n    <button class="btn primary" onclick="saveGuide()">保存指引</button>\n  </div>\n</dialog>\n\n<div id="toast"></div>\n\n<script>\nlet ST=null, VIEW=\'dash\', bStack=null;\nconst stName={open:"待办",in_progress:"执行中",done:"已完成",blocked:"受阻",cancelled:"已取消"};\nconst stOrder={open:0,in_progress:1,blocked:2,cancelled:3};\nconst $=id=>document.getElementById(id);\nconst pdlg=$(\'pdlg\'),bdlg=$(\'bdlg\'),gdlg=$(\'gdlg\');\nconst SUN=\'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>\';\nconst MOON=\'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg>\';\nconst FOLDER=\'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>\';\nconst DRIVE=\'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="7" rx="2"/><rect x="3" y="13" width="18" height="7" rx="2"/><path d="M7 7.5h.01M7 16.5h.01"/></svg>\';\n\nfunction esc(s){return String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));}\nfunction relTime(s){if(!s)return \'—\';const d=new Date(s.replace(\' \',\'T\'));const x=(Date.now()-d)/1000;\n if(isNaN(x)||x<0)return s;if(x<60)return \'刚刚\';if(x<3600)return Math.floor(x/60)+\' 分钟前\';\n if(x<86400)return Math.floor(x/3600)+\' 小时前\';return s;}\nfunction paintThemeBtn(){$(\'themeBtn\').innerHTML=document.documentElement.dataset.theme===\'dark\'?SUN:MOON;}\nfunction toggleTheme(){const r=document.documentElement;r.classList.add(\'theming\');\n r.dataset.theme=r.dataset.theme===\'dark\'?\'light\':\'dark\';\n try{localStorage.setItem(\'ta-theme\',r.dataset.theme);}catch(e){}\n paintThemeBtn();setTimeout(()=>r.classList.remove(\'theming\'),320);}\nfunction toast(m,err){const t=$(\'toast\');t.textContent=m;t.className=err?\'err show\':\'show\';\n clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove(\'show\'),3000);}\nasync function api(p,body){const r=await fetch(p,body?{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(body)}:undefined);\n const j=await r.json().catch(()=>({}));if(!r.ok||j.ok===false)throw new Error(j.message||j.error||(\'HTTP \'+r.status));return j;}\nasync function refresh(){if(pdlg.open||bdlg.open||gdlg.open)return;\n try{ST=await (await fetch(\'/api/state\')).json();\n     if(VIEW===\'dash\')renderDash();else renderSet();}catch(e){}}\nfunction chip(l,v,cls){return `<div class="chip ${cls||\'\'}"><span class="cl">${l}</span><span class="cv">${v}</span></div>`;}\nfunction switchTab(v){VIEW=v;$(\'viewDash\').style.display=v===\'dash\'?\'\':\'none\';\n $(\'viewSet\').style.display=v===\'settings\'?\'\':\'none\';\n $(\'tabDash\').className=v===\'dash\'?\'on\':\'\';$(\'tabSet\').className=v===\'settings\'?\'on\':\'\';\n refresh();}\n\n/* ---------- 看板视图 ---------- */\nfunction renderDash(){const s=ST;if(!s)return;\n $(\'meta\').textContent=`v${s.version} · 模型 ${s.llm.model}（${s.llm.provider}）${s.llm.key_configured?\'\':\' · 未配置 api_key\'} · 配置 ${s.config_path}`;\n const sc=s.scheduler;\n $(\'sched\').innerHTML=\n  (sc.running?`<div class="chip warn"><span class="cv"><span class="pulse"></span>扫描执行中</span></div>`\n             :chip(\'调度状态\',\'空闲\',\'ok\'))\n  +chip(\'已完成周期\',sc.cycles_done)\n  +chip(\'上次扫描\',relTime(sc.last_cycle_at))\n  +chip(\'扫描间隔\',sc.interval_seconds+\'s\')\n  +Object.entries(sc.last_cycle_stats).map(([k,v])=>chip(k,`处理 ${v} 任务`)).join(\'\');\n\n $(\'projects\').innerHTML=s.projects.map(p=>{\n   const cnt={};p.tasks.forEach(t=>cnt[t.status]=(cnt[t.status]||0)+1);\n   const parts=[];\n   if(cnt.open)parts.push(cnt.open+\' 待办\');\n   if(cnt.in_progress)parts.push(cnt.in_progress+\' 执行中\');\n   if(cnt.blocked)parts.push(cnt.blocked+\' 受阻\');\n   const tasks=[...p.tasks].sort((a,b)=>(stOrder[a.status]??9)-(stOrder[b.status]??9)||a.rank-b.rank||a.id.localeCompare(b.id));\n   const errHtml=p.parse_errors.map(e=>`<div class="task err"><div class="t-main"><span class="pri P0">格式</span><span class="title">${esc(e.id)}</span><span class="st st-blocked">解析失败</span></div><div class="t-meta">${esc(e.error)}</div></div>`).join(\'\');\n   const taskHtml=tasks.map(t=>`\n     <div class="task">\n       <div class="t-main"><span class="pri ${esc(t.priority)}">${esc(t.priority)}</span>\n         <span class="title" title="${esc(t.title)}">${esc(t.title)}</span>\n         <span class="st st-${esc(t.status)}">${stName[t.status]||esc(t.status)}</span></div>\n       <div class="t-meta">${esc(t.id)}${t.labels.length?\' · \'+esc(t.labels.join(\', \')):\'\'}${t.assignee?\' · 指派 \'+esc(t.assignee):\'\'}</div>\n       ${t.description?`<div class="t-desc" title="点击展开/收起" onclick="this.classList.toggle(\'open\')">${esc(t.description)}</div>`:\'\'}\n       <div class="ops">\n         ${t.status!==\'open\'&&t.status!==\'cancelled\'?`<button onclick="setStatus(\'${esc(p.name)}\',\'${esc(t.id)}\',\'open\')">重新入队</button>`:\'\'}\n         ${t.status===\'open\'||t.status===\'in_progress\'?`<button onclick="setStatus(\'${esc(p.name)}\',\'${esc(t.id)}\',\'done\')">标记完成</button>`:\'\'}\n         <button class="danger" onclick="delTask(\'${esc(p.name)}\',\'${esc(t.id)}\')">删除</button>\n       </div></div>`).join(\'\');\n   const arch=p.archived.length?`<div style="padding:0 12px 12px"><details><summary>已归档（${p.archived.length}）</summary>\n     <div class="tasks" style="padding:6px 0 0">${p.archived.slice().reverse().map(t=>`\n       <div class="task"><div class="t-main"><span class="pri ${esc(t.priority)}">${esc(t.priority)}</span>\n       <span class="title">${esc(t.title)}</span><span class="st st-done">已完成</span></div></div>`).join(\'\')}</div></details></div>`:\'\';\n   return `<div class="proj">\n     <div class="proj-head"><span class="dot"></span><h2>${esc(p.name)}</h2>\n       <span class="tag ${p.enabled?\'ok\':\'warn\'}">${p.enabled?\'启用\':\'停用\'}</span>\n       ${p.is_git_repo?\'<span class="tag">git</span>\':\'<span class="tag warn">非 git</span>\'}\n       ${p.guide_exists?\'\':\'<span class="tag bad">缺指引</span>\'}\n       <span class="pbtns"><button onclick="openGuide(\'${esc(p.name)}\')">AGENT.md</button>\n       <button onclick="openProjectEdit(\'${esc(p.name)}\')">设置</button></span></div>\n     <div class="path" style="padding-top:8px">${FOLDER}${esc(p.path)}\n       <span class="counts" style="margin-left:auto">${parts.join(\' · \')||\'无待办\'}</span></div>\n     <div class="tasks">${errHtml}${taskHtml||\'<div class="empty"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/></svg>暂无任务文件 · 到「项目与设置」添加任务</div>\'}</div>\n     ${arch}</div>`;\n }).join(\'\')||`<div class="proj"><div class="empty">还没有项目 —— 到「项目与设置」新建一个</div></div>`;\n\n $(\'logs\').textContent=s.log_tail||\'（暂无日志）\';\n}\n\n/* ---------- 设置视图 ---------- */\nfunction renderSet(){const s=ST;if(!s)return;\n if(document.activeElement&&[\'INPUT\',\'SELECT\',\'TEXTAREA\'].includes(document.activeElement.tagName))return;\n $(\'sProvider\').value=s.llm.provider;$(\'sModel\').value=s.llm.model;\n $(\'sBase\').value=s.llm.base_url;$(\'sKey\').value=s.llm.api_key||\'\';\n $(\'sTemp\').value=s.llm.temperature;$(\'sTokens\').value=s.llm.max_tokens;\n $(\'sTimeout\').value=s.llm.timeout_seconds;\n $(\'sInterval\').value=s.scheduler_cfg.interval_seconds;\n $(\'sParallel\').value=s.scheduler_cfg.max_parallel_agents;\n $(\'sPort\').value=s.web_cfg.port;\n $(\'projTable\').innerHTML=s.projects.map(p=>`\n   <div class="task" style="margin-bottom:8px">\n     <div class="t-main"><span class="dot"></span>\n       <span class="title">${esc(p.name)}</span>\n       <span class="tag ${p.enabled?\'ok\':\'warn\'}">${p.enabled?\'启用\':\'停用\'}</span>\n       ${p.is_git_repo?\'<span class="tag">git</span>\':\'<span class="tag warn">非 git</span>\'}\n       ${p.guide_exists?\'\':\'<span class="tag bad">缺指引</span>\'}</div>\n     <div class="t-meta">${esc(p.path)} · 任务目录 ${esc(p.tasks_dir||\'tasks\')} · 每轮 ${p.max_tasks_per_cycle||1} 任务</div>\n     <div class="ops">\n       <button onclick="openGuide(\'${esc(p.name)}\')">编辑 AGENT.md</button>\n       <button onclick="openProjectEdit(\'${esc(p.name)}\')">设置</button>\n       <button class="danger" onclick="delProject(\'${esc(p.name)}\')">移除</button>\n     </div></div>`).join(\'\')||\'<div class="empty">还没有项目，点上方「新建项目」</div>\';\n}\nasync function saveLlm(){try{\n  await api(\'/api/config\',{llm:{provider:$(\'sProvider\').value,model:$(\'sModel\').value,\n    base_url:$(\'sBase\').value,api_key:$(\'sKey\').value,temperature:+$(\'sTemp\').value,\n    max_tokens:+$(\'sTokens\').value,timeout_seconds:+$(\'sTimeout\').value}});\n  msg(\'msgLlm\',\'已保存并生效\');refresh();}catch(e){msg(\'msgLlm\',e.message,true);}}\nasync function saveSched(){try{\n  await api(\'/api/config\',{scheduler:{interval_seconds:+$(\'sInterval\').value,\n    max_parallel_agents:+$(\'sParallel\').value},web:{port:+$(\'sPort\').value}});\n  msg(\'msgSched\',\'已保存（端口下次启动生效）\');refresh();}catch(e){msg(\'msgSched\',e.message,true);}}\nfunction msg(id,m,err){const el=$(id);el.textContent=m;el.className=\'msg\'+(err?\' err\':\'\');\n clearTimeout(el._h);el._h=setTimeout(()=>{el.textContent=\'\';},4000);}\n\n/* ---------- 项目对话框 ---------- */\nfunction openProjectNew(){if(!ST||!ST.projects)return;\n $(\'pdlgTitle\').textContent=\'新建项目\';\n [\'pName\',\'pPath\',\'pBranch\',\'pCmds\'].forEach(i=>$(i).value=\'\');\n $(\'pTasksDir\').value=\'tasks\';$(\'pGuide\').value=\'AGENT.md\';\n $(\'pMaxTasks\').value=1;$(\'pMaxTurns\').value=40;$(\'pEnabled\').checked=true;\n $(\'pdlgErr\').textContent=\'\';pdlg.showModal();}\nfunction openProjectEdit(name){\n const p=ST.projects.find(x=>x.name===name);if(!p){toast(\'项目不存在\',true);return;}\n $(\'pdlgTitle\').textContent=\'项目设置\';\n $(\'pName\').value=p.name;$(\'pPath\').value=p.path;\n $(\'pTasksDir\').value=p.tasks_dir||\'tasks\';$(\'pGuide\').value=p.guide_file||\'AGENT.md\';\n $(\'pMaxTasks\').value=p.max_tasks_per_cycle||1;$(\'pMaxTurns\').value=p.max_agent_turns||40;\n $(\'pBranch\').value=p.allowed_branch||\'\';$(\'pCmds\').value=(p.allowed_commands||[]).join(\', \');\n $(\'pEnabled\').checked=p.enabled;\n $(\'pdlgErr\').textContent=\'\';pdlg.showModal();}\nasync function saveProject(){\n try{\n  const body={name:$(\'pName\').value,path:$(\'pPath\').value,\n    tasks_dir:$(\'pTasksDir\').value,guide_file:$(\'pGuide\').value,\n    max_tasks_per_cycle:+$(\'pMaxTasks\').value,max_agent_turns:+$(\'pMaxTurns\').value,\n    allowed_branch:$(\'pBranch\').value,enabled:$(\'pEnabled\').checked,\n    allowed_commands:$(\'pCmds\').value.split(\',\').map(s=>s.trim()).filter(Boolean)};\n  if($(\'pdlgTitle\').textContent===\'项目设置\')body.original_name=ST.projects.find(x=>x.path===$(\'pPath\').value)?.name||$(\'pName\').value;\n  const r=await api(\'/api/project\',body);\n  pdlg.close();toast(r.message);switchTab(\'settings\');}catch(e){$(\'pdlgErr\').textContent=e.message;}}\nasync function delProject(name){if(!confirm(\'确定从配置移除项目 \'+name+\'？（不会删除磁盘上的项目文件）\'))return;\n try{const r=await api(\'/api/project/delete\',{name});toast(r.message);refresh();}catch(e){toast(e.message,true);}}\n\n/* ---------- 目录选择器 ---------- */\nconst bIcons=[DRIVE,FOLDER];\nasync function browseTo(path){try{\n  const r=await api(\'/api/browse\',{path:path??\'\'});\n  bStack=r;renderBrowser();}catch(e){toast(e.message,true);}}\nfunction renderBrowser(){const r=bStack;if(!r)return;\n $(\'bCur\').textContent=r.path||\'选择盘符 / 常用目录\';\n $(\'bList\').innerHTML=(r.dirs||[]).map(d=>{\n   const isDrive=/^[A-Z]:\\\\?$/.test(d)||d.endsWith(\':\');\n   return `<div class="bitem" onclick="browseTo(\'${esc(d).replace(/\\\\\'/g,"\\\\\'")}\')">\n     ${isDrive?DRIVE:FOLDER}<span class="bpath">${esc(d)}</span></div>`;}).join(\'\')\n   ||\'<div class="bempty">（没有子目录，可直接用上面的路径框）</div>\';}\nfunction browseUp(){if(bStack&&bStack.parent)browseTo(bStack.parent);else browseTo(\'\');}\nfunction openBrowser(){$(\'bManual\').value=$(\'pPath\').value;bdlg.showModal();\n browseTo($(\'pPath\').value||\'\');}\nfunction pickPath(){const v=$(\'bManual\').value.trim()||(bStack&&bStack.path);\n if(v){$(\'pPath\').value=v;bdlg.close();}}\n\n/* ---------- AGENT.md 编辑 ---------- */\nasync function openGuide(name){try{\n  const r=await api(\'/api/guide?project=\'+encodeURIComponent(name));\n  $(\'gdlgTitle\').textContent=\'编辑指引 · \'+name;\n  $(\'gdlgFile\').textContent=r.file;\n  $(\'gContent\').value=r.content;\n  $(\'gdlgErr\').textContent=\'\';gdlg.showModal();}catch(e){toast(e.message,true);}}\nasync function saveGuide(){try{\n  const name=$(\'gdlgTitle\').textContent.replace(\'编辑指引 · \',\'\');\n  const r=await api(\'/api/guide\',{project:name,content:$(\'gContent\').value});\n  gdlg.close();toast(\'指引已保存：\'+r.file);}catch(e){$(\'gdlgErr\').textContent=e.message;}}\n\n/* ---------- 任务/扫描 ---------- */\nasync function doScan(){const b=$(\'scanBtn\');try{b.disabled=true;\n  const r=await api(\'/api/scan\',{});toast(r.message);}catch(e){toast(e.message,true);}\n  finally{setTimeout(()=>b.disabled=false,1200);}refresh();}\nasync function setStatus(p,id,st){try{await api(\'/api/task/status\',{project:p,id,status:st});toast(\'已更新\');refresh();}catch(e){toast(e.message,true);}}\nasync function delTask(p,id){if(!confirm(\'确定删除任务 \'+id+\'？\'))return;\n try{await api(\'/api/task/delete\',{project:p,id});toast(\'已删除\');refresh();}catch(e){toast(e.message,true);}}\n\npaintThemeBtn();refresh();setInterval(()=>{if(!document.hidden)refresh();},5000);\n</script>\n</body>\n</html>\n'
